/**
 * Two different kinds of decision, deliberately kept in different functions.
 *
 * The single most important rule in this engine is that the model never
 * decides an outcome. But "the model does not decide" is not one rule, it is
 * two, because Liu Bei's life contains two completely different kinds of
 * decision point:
 *
 *   1. CAN I DO IT?      -> an ability check. Luck matters. Roll a die.
 *   2. WHAT WILL IT COST? -> a moral choice. Luck does NOT matter. Both paths
 *                            are available; they simply cost different things.
 *
 * Collapsing these into one dice roll is the standard mistake and it destroys
 * the subject: if "携民渡江" can fail because you rolled a 12, then the game is
 * about luck, not about character. Historically it did not fail — it cost him
 * everything material and bought him everything that mattered later.
 *
 * So: `check()` rolls. `weigh()` does not. Nothing here ever reads a model
 * suggestion as an outcome; hints are clamped to a legal band first.
 */

import { rollCheck } from './rng.js'

/** The five attributes. Liu Bei is deliberately mediocre in four of them. */
export const ATTRIBUTES = ['wu', 'tong', 'zhi', 'zheng', 'mei']

export const ATTRIBUTE_LABELS = {
  wu: '武',
  tong: '统',
  zhi: '智',
  zheng: '政',
  mei: '魅'
}

/** Difficulty bands, so hints and defaults agree on the same numbers. */
export const DIFFICULTY_BANDS = {
  trivial: 20,
  easy: 35,
  normal: 50,
  hard: 65,
  severe: 80,
  desperate: 92
}

/**
 * Legal clamp for a model-supplied difficulty hint.
 *
 * The model is allowed to say "this feels hard". It is NOT allowed to say
 * "this is impossible" (which would let it veto the player) or "this is
 * trivial" (which would let it hand out wins). 10..95 keeps both the
 * automatic-success and automatic-failure bands out of reach.
 */
const HINT_FLOOR = 10
const HINT_CEIL = 95

export const MARGIN_CRITICAL = 20

/** Outcomes, ordered from best to worst. */
export const OUTCOME = {
  CRITICAL_SUCCESS: 'critical_success',
  SUCCESS: 'success',
  PARTIAL: 'partial',
  FAILURE: 'failure',
  CRITICAL_FAILURE: 'critical_failure'
}

const OUTCOME_RANK = {
  [OUTCOME.CRITICAL_SUCCESS]: 2,
  [OUTCOME.SUCCESS]: 1,
  [OUTCOME.PARTIAL]: 0,
  [OUTCOME.FAILURE]: -1,
  [OUTCOME.CRITICAL_FAILURE]: -2
}

/**
 * Clamp a difficulty hint into the legal band.
 * Returns `fallback` when the hint is missing or not a finite number.
 */
export function clampDifficulty(hint, fallback) {
  const base = Number.isFinite(fallback) ? fallback : DIFFICULTY_BANDS.normal
  if (!Number.isFinite(hint)) {
    return base
  }
  const rounded = Math.round(hint)
  return Math.min(HINT_CEIL, Math.max(HINT_FLOOR, rounded))
}

/**
 * Validate a model-supplied attribute hint.
 * Unknown or missing attributes fall back to the caller's default; the model
 * cannot invent a sixth attribute to roll against.
 */
export function clampAttribute(hint, fallback) {
  if (typeof hint === 'string' && ATTRIBUTES.includes(hint)) {
    return hint
  }
  return ATTRIBUTES.includes(fallback) ? fallback : 'mei'
}

/** Map a margin to an outcome band. */
export function outcomeOf(margin) {
  if (margin >= MARGIN_CRITICAL) return OUTCOME.CRITICAL_SUCCESS
  if (margin >= 0) return OUTCOME.SUCCESS
  if (margin > -MARGIN_CRITICAL) return OUTCOME.PARTIAL
  if (margin > -2 * MARGIN_CRITICAL) return OUTCOME.FAILURE
  return OUTCOME.CRITICAL_FAILURE
}

/** Rank an outcome so callers can compare two bands without string tables. */
export function rankOf(outcome) {
  return OUTCOME_RANK[outcome] ?? 0
}

/**
 * Sum the situational modifiers the engine recognises.
 *
 * Modifiers are supplied by the CALLER (the act resolver), not by the model:
 * they come from state (troop ratio, weather, standing with the target, whether
 * the target has a reason to trust you). The model may describe them in prose
 * but cannot add a number to this list.
 */
export function sumModifiers(modifiers) {
  if (!Array.isArray(modifiers)) {
    return 0
  }
  let total = 0
  for (const modifier of modifiers) {
    const value = modifier?.value
    if (Number.isFinite(value)) {
      total += Math.trunc(value)
    }
  }
  return total
}

/**
 * Run one ability check.
 *
 * @param {object} input
 * @param {number} input.state      RNG state from the save.
 * @param {object} input.attrs      { wu, tong, zhi, zheng, mei }
 * @param {string} input.attribute  which attribute to test (already clamped)
 * @param {number} input.difficulty already clamped
 * @param {Array}  [input.modifiers] engine-derived situational modifiers
 * @returns {{ outcome, margin, roll, total, difficulty, attribute, state, modifiers }}
 */
export function check(input) {
  const attribute = clampAttribute(input.attribute, 'mei')
  const difficulty = clampDifficulty(input.difficulty, DIFFICULTY_BANDS.normal)
  const attrs = input.attrs ?? {}
  const raw = Number(attrs[attribute])
  const attributeValue = Number.isFinite(raw) ? Math.trunc(raw) : 0
  const modifiers = Array.isArray(input.modifiers) ? input.modifiers : []
  const modifierTotal = sumModifiers(modifiers)

  const rolled = rollCheck(input.state)
  const total = rolled.value + attributeValue + modifierTotal
  const margin = total - difficulty

  return {
    outcome: outcomeOf(margin),
    margin,
    roll: rolled.value,
    total,
    difficulty,
    attribute,
    attributeValue,
    modifierTotal,
    modifiers,
    state: rolled.state
  }
}

/**
 * Weigh a moral choice. NO DICE.
 *
 * Each option declares what it costs in the three counters that actually
 * compound in this story (声望 fame / 信义 trust / 人才 talent), plus any
 * concrete material effect. The function returns the same shape for every
 * option so the model can present a fair comparison without ever inventing a
 * consequence.
 *
 * @param {Array<{id:string, label:string, effects:object, note?:string}>} options
 * @returns {Array<{id, label, effects, note}>}  unchanged but normalised
 */
export function weigh(options) {
  if (!Array.isArray(options)) {
    return []
  }
  return options.map((option) => ({
    id: String(option?.id ?? ''),
    label: String(option?.label ?? ''),
    effects: normaliseEffects(option?.effects),
    note: typeof option?.note === 'string' ? option.note : ''
  }))
}

/**
 * Normalise an effects object to a fixed key set.
 *
 * Fixed keys matter: a typo like `famee` must not silently do nothing while
 * the model narrates a reputation gain that never happened. Unknown keys are
 * dropped, known keys are coerced to integers.
 */
export const EFFECT_KEYS = ['fame', 'trust', 'talent', 'gold', 'grain', 'troops', 'hp']

export function normaliseEffects(effects) {
  const out = {}
  for (const key of EFFECT_KEYS) {
    const value = effects?.[key]
    out[key] = Number.isFinite(value) ? Math.trunc(value) : 0
  }
  return out
}

/** Counter keys (bounded 0..100) versus resource keys (bounded by kind). */
export const COUNTER_KEYS = ['fame', 'trust', 'talent']
export const RESOURCE_KEYS = ['gold', 'grain', 'troops', 'hp']

/**
 * Apply an effects object to a mutable bag, touching ONLY the keys in `keys`.
 *
 * The explicit key list matters: one effects object in acts.json mixes
 * counters (fame/trust/talent) with resources (gold/grain/troops/hp), and a
 * blind copy would write `gold` into the counters bag and `fame` into the
 * resources bag. Those ghost keys then survive a save round-trip and show up in
 * the digest as phantom wealth.
 *
 * Clamping rules:
 *   · fame/trust/talent are 0..100 and never wrap — a moral disaster floors at
 *     0 rather than wrapping to 99, which would turn catastrophe into a jackpot.
 *   · gold/grain/troops floor at 0.
 *   · hp is capped at 100.
 */
export function applyEffects(bag, effects, keys = EFFECT_KEYS) {
  const normalised = normaliseEffects(effects)
  for (const key of keys) {
    const delta = normalised[key]
    if (delta === 0) continue
    const current = Number.isFinite(bag[key]) ? bag[key] : 0
    const next = current + delta
    if (COUNTER_KEYS.includes(key)) {
      bag[key] = Math.min(100, Math.max(0, next))
    } else if (key === 'hp') {
      bag[key] = Math.min(100, Math.max(0, next))
    } else {
      bag[key] = Math.max(0, next)
    }
  }
  return bag
}
